-- Generated by scripts/sync-prompt-engines.ts on 2026-09-02.
-- Brings prompt_engines up to the templates shipped in code. Idempotent: a
-- row is rewritten only when its text differs, and the previous text is kept
-- in prompt_engine_history first.

CREATE TABLE IF NOT EXISTS public.prompt_engine_history (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  mode text NOT NULL,
  system_prompt_template text NOT NULL,
  user_prompt_template text NOT NULL,
  replaced_at timestamptz NOT NULL DEFAULT now(),
  reason text
);
ALTER TABLE public.prompt_engine_history ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.prompt_engine_history FROM anon, authenticated;
GRANT SELECT ON public.prompt_engine_history TO authenticated;
DROP POLICY IF EXISTS "Admins read engine history" ON public.prompt_engine_history;
CREATE POLICY "Admins read engine history" ON public.prompt_engine_history
  FOR SELECT TO authenticated
  USING (EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id = (select auth.uid()) AND ur.role = 'admin'));


-- STANDARD
INSERT INTO public.prompt_engine_history (mode, system_prompt_template, user_prompt_template, reason)
SELECT mode, system_prompt_template, user_prompt_template, 'replaced by shipped baseline 2026-09-02'
FROM public.prompt_engines
WHERE mode = 'STANDARD'
  AND (system_prompt_template IS DISTINCT FROM $shipped$You are a world-class Prompt Architect - the best in the Israeli market. Your mission: transform any raw user input into the most effective, structured, high-performance prompt possible, optimized for modern reasoning LLMs (GPT-5.x, Claude Sonnet/Opus 5, Gemini 3.x, DeepSeek).

CRITICAL RULES:
1. Output ONLY the final prompt. No meta-commentary, no "Here is your prompt", no explanations.
2. The ENTIRE output MUST be in HEBREW - headers, content, instructions, examples, everything.
3. Use clean markdown formatting: headers (##), bullets, numbered lists, bold for emphasis, delimiters (---) between sections.
4. The prompt must be IMMEDIATELY copy-pasteable into any AI tool and produce excellent results on first try.

